import{_ as i,a0 as u,w as a,s,ao as l,I as p,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"戴文的Linux內核專題：26 配置內核 (22) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：26 配置內核 (22) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：26 配置內核 (22) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：26 配置內核 (22) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/26 The Linux Kernel--Configuring the Kernel Part 22","title":"戴文的Linux內核專題：26 配置內核 (22)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/26 The Linux Kernel--Configuring the Kernel Part 22.md","filePath":"[post].md"}'),c={name:"The Linux Kernel/26 The Linux Kernel--Configuring the Kernel Part 22.md"};function m(g,e,d,f,x,L){const r=u("Link");return a(),s("div",null,[e[11]||(e[11]=l('<h1 id="戴文的linux內核專題-26-配置內核-22" tabindex="-1">戴文的Linux內核專題：26 配置內核 (22) <a class="header-anchor" href="#戴文的linux內核專題-26-配置內核-22" aria-label="Permalink to “戴文的Linux內核專題：26 配置內核 (22)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.703/.jpg" alt=""></p><p>你好！本篇我們將繼續配置&quot;kernel hacks&quot;,接着我們會配置整個安全系統。</p><p>Alpha和s390處理器需要配置下一個特性(Force weak per-cpu definitions)。這個特性修復了一個在這類處理器中普遍存在的尋址問題。其他的處理器無需啓用這個特性。</p><p>內核轉儲可以用這個特殊的調試工具測試(Linux Kernel Dump Test Tool Module)。這個軟件會允許內核開發者觸發一個假錯誤來導致內核轉儲。內核開發者可以保證轉儲成功執行。</p><p>內核提供了不同的錯誤注射模組來允許內核開發者測試通知(CPU notifier error injection module)、 (PM notifier error injection module) 和 (Memory hotplug notifier error injection module)。通知器提醒系統硬件還在，這對熱插拔很重要。這些錯誤注射模組在這些通知系統中觸發一個錯誤，那麼開發者就可以測試通知系統的錯誤處理能力了。</p><p>&quot;Fault-injection framework&quot;驅動提供了不同的用於測試錯誤處理的工具。</p><p>&quot;Latency measuring infrastructure&quot;驅動提供了延遲檢測工具LatencyTop，以找出用户空間中由於內核執行/任務而被阻礙/干擾的對象。</p><p>下面，我們有一個子菜單名為&quot;Tracers&quot;，它包含了不同追蹤器的列表。追蹤器是一段監視不同內核函數的代碼。每次某個特定的函數啓動，追蹤器將被調用來檢測函數。</p><p>下面的模組用來測試紅黑樹庫的性能(Red-Black tree test)。紅黑樹是一個排序和搜索算法。</p><p>下面的特性是相同的除了用來測試區間樹庫(Interval tree test)。</p><p>在啓動遠程特定系統時，內核同樣可以在其他系統上調試FireWire (Remote debugging over FireWire early on boot) 和 (Remote debugging over FireWire with firewire-ohci)。</p><p>printk()函數可以用來打印不同的調試信息，如果這個特性啓用的話(Enable dynamic printk() support)。&quot;printk()&quot;是一個常被討論的系統調用，所以記住這個打印內核相關消息。</p><p>這是一個直接內存訪問(DMA)調試驅動(Enable debugging of DMA-API usage)。</p><p>Atomic64自我測試檢查系統是否支持原子操作(Perform an atomic64_t self-test at boot)。這是一個32位系統執行64位操作。</p><p>這個驅動提供了對於所有可能的RAID6恢復系統的自檢(Self test for hardware accelerated raid6 recovery)。</p><p>注意：自檢是底層測試並且在絕大多數系統硬件和軟件開啓和執行前偵查軟件。自檢搜索硬件，失敗的設備等等。自檢也可能被編成應用以測試它本身。</p><p>在&quot;Kernel Hacking&quot;菜單中(如果你是用的是像ncurses那樣的菜單接口)，有一個名為&quot;Sample kernel code&quot;的子菜單。在以後的文章中，我們會討論如何實現自定義/自制內核模組。只要記住這裏是啓用你自己的模組。</p><p><img src="http://www.linux.org/attachments/kernel_22-png.704/" alt=""></p><p>Kernel GNU DeBugger (KGDB)(內核調試器)有許多特性可以啓用或者禁用(KGDB: kernel debugger)。這個調試器只工作在通過串行連接的兩個Linux系統之間。</p><p>這個特性提供在啓動時顯示額外bzimage解壓消息(Enable verbose x86 bootup info messages)。在內核配置的開始部分你設置了內核加密。</p><p>printk()打印不同的消息到dmsg的啓動界面，但是在串行和控制台驅動加載後。啓用這個驅動會使printk()更早打印信息(Early printk)。</p><p>下一個驅動和上面的一樣，但是使用EHCI端口(Early printk via EHCI debug port)。</p><p>內核可以被設置來觀察堆棧溢出，這樣內核可以更好地管理錯誤(Check for stack overflows)。內核會執行的更慢，但是溢出不會造成如此大的損害。</p><p>通過啓用這個，內核頁面可用debugfs見到(Export kernel pagetable layout to userspace via debugfs)。然而，這個會使內核變慢。這個用於調試目的。</p><p>內核的寫入錯誤可以被這個特性捕捉到(Write protect kernel read-only data structures)。這個選項會使內核的只讀數據編程進入寫保護模式。此調試工具會損害內核的速度。該調試工具還有一個用來調試其自身的工具(Testcase for the DEBUG_RODATA feature)。</p><p>為了防止被修改過代碼的模組執行(由於一個錯誤)，接着啓用這個保護性特性 (Set loadable kernel module data as NX and text as RO)。這個調試工具由這個驅動提供(Testcase for the NX non-executable stack feature)。</p><p>使用這個選項，內核可以一次刷新一個TLB條目或者整張表 (Set upper limit of TLB entries to flush one-by-one)。</p><p>下一個特性是IOMMU調試特性(Enable IOMMU debugging)。這是另外一個調試測試，禁用一些IOMMU特性來用於測試穩定性(Enable IOMMU stress-test mode)。IOMMU代表&quot;input/output memory management unit&quot;(輸入/輸出內存管理單元)。</p><p>啓用這個選項回事內核以30s的間隔在change_page_attr()系統調用上執行單端測試。這個系統調用會改變頁的屬性。</p><p>任何被標以&quot;inline&quot;的內核代碼，如果沒有被表明的也同樣會被GCC操作(Allow gcc to uninline functions marked)。GCC編譯器會增加使得代碼更好的代碼(GCC擅長這麼做)。然而，一些代碼不想被GCC操作。</p><p>下面的驅動提供了對&quot;copy_from_user()&quot;系統調用的基本測試（Strict copy size checks)。copy_fcrom_user()從用户空間拷貝數據塊到內核空間中。</p><p>這裏還有一個自檢；它用於NMI(NMI Selftest)。</p><p>現在，我們會進入&quot;Security Options&quot;，如果你使用像ncurses的基於菜單的接口時。第一個選項允許訪問內核中存儲的鍵和驗證令牌(Enable access key retention support)。這有很多原因用到，像訪問加密文件系統。</p><p>下面的選項用於創建並密封/開啓鍵((TRUSTED KEYS))。加密的鍵使用這個驅動加密/解密(ENCRYPTED KEYS)。</p><p>啓用這個特性鍵可以在/proc中看到(Enable the /proc/keys file by which keys may be viewed)。</p><p>使用這個安全特性，額外的限制可以應用到syslog中(Restrict unprivileged access to the kernel syslog)。</p><p>如果啓用這個選項，那麼用户可以選擇不同的安全模組(Enable different security models)。不然，將會使用默認。如果你不完全理解安全或者如果你對使用默認感到沒問題，那麼就禁用它。</p><p>這個驅動提供了securityfs文件系統(Enable the securityfs filesystem)。</p><p>當啓用這個特性後，鈎子將會被增加到網絡和套接字安全中(Socket and Networking Security Hooks)。這些鈎子是訪問控制。</p><p>IPSec網絡鈎子(also called XFRM networking hooks)在這個選項啓用後實現(XFRM (IPSec) Networking Security Hooks)。安全鈎子同樣可被文件使用(Security hooks for pathname based access control)。</p><p>下一個驅動提供了對Intel可信賴執行技術的支持(Enable Intel(R) Trusted Execution Technology (Intel(R) TXT))。</p><p>用户可以設置無法為用户空間保留的內存尋址範圍(Low address space for LSM to protect from user allocation)。開始點是0。用户在此選項中輸入結束點。對於大多數平台而言，65536是一個建議值。</p><p>SELinux(在內核安全的文章中提到)是一種流行的Linux安全模組(NSA SELinux Support)。SELinux存在很多選項和特性。啓動參數決定了當內核執行(NSA SELinux boot parameter)時SELinux是否啓動{1}或者不啓動{0}。SELinux可以被配置成在root用户需要時臨時禁止(NSA SELinux runtime disable)。用户可以啓用這個特性開發並測試新的策略(NSA SELinux Development Support)。AVC統計被這個特性收集並被存儲 (NSA SELinux AVC Statistics)。對於checkreqprot標誌有一個默認設置；&quot;1&quot;意味着SElinux會檢查應用請求的保護，&quot;0&quot;會默認使用內核對mmap和mprotect系統調用的保護(NSA SELinux checkreqprot default value)。存在很多的SElinux策略;用户可以設置他們不希望SELinux excede的最新版本(NSA SELinux maximum supported policy format version)。</p><p>另外一個Linux安全模組(LSM),SMACK,也被內核支持(Simplified Mandatory Access Control Kernel Support)。</p><p>TOMOYO是另外一個被支持的LSM(TOMOYO Linux Support)。在學習模式中允許被添加的最大條目數目在下面的特性中設置(Default maximal count for audit log)。接下來，這個選項允許/禁用TOMOYO在沒有策略加載器下被激活(Activate without calling userspace policy loader)。策略加載器的位置在這裏被配置((/sbin/tomoyo-init) Location of userspace policy loader)，觸發執行的可執行文件在這裏設置((/sbin/init) Trigger for calling userspace policy loader)。</p><p>再説一次，內核支持另外一個LSM - APPArmor(AppArmor support)。像SELinux一樣，可以為AppArmor設置默認的啓動參數(AppArmor boot parameter default value)。</p><p>Yama是另外一個LSM(Yama support)。如果啓用這個特性Yama可以與另外一個LSM一起使用(Yama stacked with other LSMs)。</p><p>這個驅動讓內核可以使用多個密鑰鏈來驗證進程(Digital signature verification using multiple keyrings)。</p><p>非對稱鍵在這個特性中支持(Enable asymmetric keys support)。</p><p>內核可以保存並維護一個哈希和重要系統文件的列表(Integrity Measurement Architecture(IMA))。那麼，如果惡意軟件改變了一個重要的文件，內核會知道因為文件或者可執行文件被使用時內核會檢測哈希值。強烈建議啓用這個特性。</p><p>如果啓用這個特性會加入額外的安全屬性(EVM support)。可以用下面的選項設置版本(EVM HMAC version)。有兩個選項分別是version 1和2。</p><p>記住所有的Linux安全模組的不同了麼(LSMs)？好的，下面可以設置默認模組(Default security module (AppArmor))。</p><p>下一篇中，我們會配置&quot;Cryptographic API&quot;。我估計還會剩下兩篇文章。在這之後，我們會討論其他的內核主題。</p><p>先睹為快：本篇之後，關於配置還有一篇。接着，我們會完成編譯並安裝內核。</p><p>致我的粉絲：你隨意給我致信或者給我電子郵件來建議你希望在以後的內核文章中想要看到的主題。我已經收到了一些來自這個系列讀者的一些建議。請隨意給我更多建議。</p><hr>',57)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),o(r,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-22.5017/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-22.5017/",-1)])]),_:1})]),p("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:n(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const k=i(c,[["render",m]]);export{T as __pageData,k as default};
